LISTE_IMPORTATION_HISTORIQUE = (
    (gettext_lazy("1-	EXW – Ex-Works – À l’usine \n Le vendeur (expéditeur) met à disposition les marchandises transportées dans un endroit convenu (obligation minimale pour le vendeur). L’acheteur supporte tous les coûts de transport et de formalités."),gettext_lazy("1-	EXW – Ex-Works – À l’usine \n Le vendeur (expéditeur) met à disposition les marchandises transportées dans un endroit convenu (obligation minimale pour le vendeur). L’acheteur supporte tous les coûts de transport et de formalités.")),
    (gettext_lazy("2-	FCA – Free-CArrier – Franco-transporteur\n  Le vendeur livre la marchandise au destinataire désigné et payé par l’acheteur. Le transfert des risques est matérialisé lors de cette opération. Si la livraison est effectuée dans les locaux du vendeur, il est responsable du chargement de la marchandise. Si la livraison a lieu dans un autre endroit, le vendeur n’est plus responsable du déchargement."), gettext_lazy("2-	FCA – Free-CArrier – Franco-transporteur\n  Le vendeur livre la marchandise au destinataire désigné et payé par l’acheteur. Le transfert des risques est matérialisé lors de cette opération. Si la livraison est effectuée dans les locaux du vendeur, il est responsable du chargement de la marchandise. Si la livraison a lieu dans un autre endroit, le vendeur n’est plus responsable du déchargement.")),
    (gettext_lazy("3-	CPT – Carriage Paid To – Port payé jusqu’à  \n La marchandise est livrée au premier transporteur à l’étranger, frais payés par le vendeur, sans assurance pour le transport. L’acheteur assume les risques et tous les autres frais encourus par la marchandise dès la remise de la marchandise au premier transporteur. L’acheteur prend en charge toutes les opérations qui ont lieu à l’arrivée."),gettext_lazy("3-	CPT – Carriage Paid To – Port payé jusqu’à  \n La marchandise est livrée au premier transporteur à l’étranger, frais payés par le vendeur, sans assurance pour le transport. L’acheteur assume les risques et tous les autres frais encourus par la marchandise dès la remise de la marchandise au premier transporteur. L’acheteur prend en charge toutes les opérations qui ont lieu à l’arrivée.")),
    (gettext_lazy("4-	CIP – Carriage Insurance Paid to – Port payé, assurance comprise jusqu’à DAP \n Règle Incoterms identique au CPT avec comme seule différence l’assurance : le vendeur prend en charge l’assurance du transport."),gettext_lazy("4-	CIP – Carriage Insurance Paid to – Port payé, assurance comprise jusqu’à DAP \n Règle Incoterms identique au CPT avec comme seule différence l’assurance : le vendeur prend en charge l’assurance du transport.")),
    (gettext_lazy("5-	DAP – Delivered At Place – Rendu au lieu de destination \n Le vendeur prend en charge le transport des marchandises jusqu’au point de livraison convenu. Il assume les coûts et les risques jusqu’à ce point. L’acheteur supporte le déchargement et le dédouanement import."),gettext_lazy("5-	DAP – Delivered At Place – Rendu au lieu de destination \n Le vendeur prend en charge le transport des marchandises jusqu’au point de livraison convenu. Il assume les coûts et les risques jusqu’à ce point. L’acheteur supporte le déchargement et le dédouanement import.")),
    (gettext_lazy("6-	DPU – Delivred at place unloaded, rendu au lieu de destination (ancien DAT) \n Le vendeur organise le transport et paie le déchargement au lieu de destination. Une fois au terminal l’acheteur est responsable de la marchandise et doit effectuer les formalités d’importation et s’acquitte des droits et taxes liés."),gettext_lazy("6-	DPU – Delivred at place unloaded, rendu au lieu de destination (ancien DAT) \n Le vendeur organise le transport et paie le déchargement au lieu de destination. Une fois au terminal l’acheteur est responsable de la marchandise et doit effectuer les formalités d’importation et s’acquitte des droits et taxes liés.")),
    (gettext_lazy("7-	DDP – Delivered Duty Paid – Rendu droits acquittés \n Le vendeur livre la marchandise à l’acheteur en ayant tout pris en charge, y compris les formalités douanières import et le paiement des droits et taxes (Obligation maximal pour le vendeur)."),gettext_lazy("7-	DDP – Delivered Duty Paid – Rendu droits acquittés \n Le vendeur livre la marchandise à l’acheteur en ayant tout pris en charge, y compris les formalités douanières import et le paiement des droits et taxes (Obligation maximal pour le vendeur).")),
    (gettext_lazy("8-	FAS (Free alongside ship) \n Le vendeur règle les frais de transport jusqu’au port d’embarquement et effectue les formalités d’exportation. La marchandise est livrée le long du navire dans le port désigné par l’acheteur. Cette livraison marque le transfert des risques, des frais et des formalités à l’acheteur. L’Incoterm FAS impose au vendeur l’obligation de dédouaner le fret à l’exportation."), gettext_lazy("8-	FAS (Free alongside ship) \n Le vendeur règle les frais de transport jusqu’au port d’embarquement et effectue les formalités d’exportation. La marchandise est livrée le long du navire dans le port désigné par l’acheteur. Cette livraison marque le transfert des risques, des frais et des formalités à l’acheteur. L’Incoterm FAS impose au vendeur l’obligation de dédouaner le fret à l’exportation.")),
    (gettext_lazy("9-	FOB (Free on board) \n Le vendeur livre la marchandise sur le navire au port d’embarquement convenu. Le transfert des charges et des risques se fait lorsque la marchandise est à bord du navire. Le vendeur doit dédouaner la marchandise."),gettext_lazy("9-	FOB (Free on board) \n Le vendeur livre la marchandise sur le navire au port d’embarquement convenu. Le transfert des charges et des risques se fait lorsque la marchandise est à bord du navire. Le vendeur doit dédouaner la marchandise.")),
    (gettext_lazy("10-  CFR (Cost and freight) \n Le vendeur se charge du transport principal jusqu’au port de destination. Il se charge des formalités d’export et doit s’acquitter des droits et taxes liés. Le transfert de frais à lieu à l’arrivée des marchandises au port d’arrivée, mais le vendeur n’est plus responsable de la marchandise dès que celle-ci a été chargée sur le port de départ."),gettext_lazy("10-  CFR (Cost and freight) \n Le vendeur se charge du transport principal jusqu’au port de destination. Il se charge des formalités d’export et doit s’acquitter des droits et taxes liés. Le transfert de frais à lieu à l’arrivée des marchandises au port d’arrivée, mais le vendeur n’est plus responsable de la marchandise dès que celle-ci a été chargée sur le port de départ.")),
    (gettext_lazy("11-	CIF (Cost, insurance and freight) \n Le vendeur livre la marchandise sur le navire au port d’embarquement convenu. Le vendeur se charge des formalités d’export et règles les droits et taxes liés. Le transfert des frais se fait au port de destination mais le transfert des risques a lieu au port de départ. L’acheteur prend en charge les frais à l’arrivée des marchandises au port de destination, et les formalités à l’import."),gettext_lazy("11-	CIF (Cost, insurance and freight) \n Le vendeur livre la marchandise sur le navire au port d’embarquement convenu. Le vendeur se charge des formalités d’export et règles les droits et taxes liés. Le transfert des frais se fait au port de destination mais le transfert des risques a lieu au port de départ. L’acheteur prend en charge les frais à l’arrivée des marchandises au port de destination, et les formalités à l’import.")),
)

